(r, big) => {
    const hi = big ? 999 : 20, LIM = 1000000000;
    const tdiv = (a, b) => { const q = Math.floor(Math.abs(a) / Math.abs(b)); return (a < 0) === (b < 0) ? q : -q; };
    // each builder returns { s, v }, tracking the value so no step overflows or divides by zero
    const factor = depth => {
      if (depth > 0 && r.bool(big ? 0.25 : 0.35)) { const e = expr(depth - 1, r.int(1, 3)); return { s: "(" + e.s + ")", v: e.v }; }
      const x = r.int(0, hi); return { s: String(x), v: x };
    };
    const term = depth => {
      let f = factor(depth), s = f.s, v = f.v;
      const extra = r.bool(0.4) ? r.int(1, 2) : 0;
      for (let k = 0; k < extra; k++) {
        const g = factor(depth);
        let op = r.pick(["*", "/"]);
        if (op === "*" && Math.abs(v * g.v) > 1000000) op = "/";
        if (op === "/" && g.v === 0) op = "*";
        if (op === "*" && Math.abs(v * g.v) > 1000000) break;
        v = op === "*" ? v * g.v : tdiv(v, g.v);
        s += op + g.s;
      }
      return { s, v };
    };
    const expr = (depth, terms) => {
      let t = term(depth), s = t.s, v = t.v;
      for (let k = 1; k < terms; k++) {
        const u = term(depth);
        let op = r.pick(["+", "-"]);
        if (Math.abs(op === "+" ? v + u.v : v - u.v) > LIM) op = op === "+" ? "-" : "+";
        v = op === "+" ? v + u.v : v - u.v;
        s += op + u.s;
      }
      return { s, v };
    };
    if (!big) return [expr(2, r.int(1, 4)).s];
    // one 100-deep chain, then a long flat run of shallow terms
    let deep = String(r.int(0, hi));
    for (let d = 0; d < 100; d++) deep = "(" + r.int(0, hi) + "+" + deep + ")";
    let s = deep;
    while (s.length < 95000) s += "+" + term(3).s;
    return [s];
  }

