function evalNested(s: string): number {
  let i = 0;
  const expr = (): number => {
    let total = term();
    while (i < s.length && (s[i] === "+" || s[i] === "-")) {
      const op = s[i++];
      const t = term();
      total = op === "+" ? total + t : total - t;
    }
    return total;
  };
  const term = (): number => {
    let v = factor();
    while (i < s.length && (s[i] === "*" || s[i] === "/")) {
      const op = s[i++];
      const f = factor();
      v = op === "*" ? v * f : (v / f) | 0; // | 0 truncates toward zero for 32-bit values
    }
    return v;
  };
  const factor = (): number => {
    if (s[i] === "(") {
      i++;
      const v = expr();
      i++; // skip ')'
      return v;
    }
    let n = 0;
    while (i < s.length && s[i] >= "0" && s[i] <= "9") n = n * 10 + (s.charCodeAt(i++) - 48);
    return n;
  };
  return expr();
}

