class Solution:
    def evalNested(self, s: str) -> int:
        i = 0

        def div(a, b):
            q = abs(a) // abs(b)
            return q if (a < 0) == (b < 0) else -q

        def expr():
            nonlocal i
            total = term()
            while i < len(s) and s[i] in "+-":
                op = s[i]
                i += 1
                t = term()
                total = total + t if op == "+" else total - t
            return total

        def term():
            nonlocal i
            v = factor()
            while i < len(s) and s[i] in "*/":
                op = s[i]
                i += 1
                f = factor()
                v = v * f if op == "*" else div(v, f)
            return v

        def factor():
            nonlocal i
            if s[i] == "(":
                i += 1
                v = expr()
                i += 1  # skip ')'
                return v
            j = i
            while i < len(s) and s[i].isdigit():
                i += 1
            return int(s[j:i])

        return expr()

