function evalNested(s: string): number {
  let terms: number[] = [];
  let op = "+", num = 0;
  const frames: [number[], string][] = [];
  const apply = () => {
    if (op === "+") terms.push(num);
    else if (op === "-") terms.push(-num);
    else if (op === "*") terms.push(terms.pop()! * num);
    else terms.push((terms.pop()! / num) | 0);
  };
  const sum = (a: number[]) => a.reduce((x, y) => x + y, 0);
  for (const c of s) {
    if (c >= "0" && c <= "9") num = num * 10 + (c.charCodeAt(0) - 48);
    else if (c === "(") {
      frames.push([terms, op]);
      terms = [];
      op = "+";
    } else if (c === ")") {
      apply();
      num = sum(terms);
      [terms, op] = frames.pop()!;
    } else {
      apply();
      op = c;
      num = 0;
    }
  }
  apply();
  return sum(terms);
}

