        terms, op, num, frames = [], "+", 0, []

        def apply():
            if op == "+":
                terms.append(num)
            elif op == "-":
                terms.append(-num)
            elif op == "*":
                terms.append(terms.pop() * num)
            else:
                a = terms.pop()
                q = abs(a) // abs(num)
                terms.append(q if (a < 0) == (num < 0) else -q)

        for c in s:
            if c.isdigit():
                num = num * 10 + int(c)
            elif c == "(":
                frames.append((terms, op))
                terms, op = [], "+"
            elif c == ")":
                apply()
                num = sum(terms)
                terms, op = frames.pop()
            else:
                apply()
                op, num = c, 0
        apply()
        return sum(terms)

